arguments.command:
cd /workspace/src && python3 - <<'PY'
p='image_bits.hpp'
s=open(p).read()
s=s.replace("    OFF_INLINE = 25,   OFF_INLINE_W = 94,","    OFF_INLINE = 25,   OFF_INLINE_W = 94,\n    OFF_DIRECT3 = 153,")
open(p,'w').write(s)

p='image.cpp'
s=open(p).read()

# VEdge bulk_child member
s=s.replace("""struct VEdge {
    uint32_t key;
    uint32_t stage;
    uint32_t cell;
};""","""struct VEdge {
    uint32_t key;
    uint32_t stage;
    uint32_t cell;
    bool bulk_child = false;
};""")

old_visit_tail = """        bool ok = true;
        if (type == 4 || type == 5) {
            ok = decode_inline(w, static_cast<int>(off), n);
            if (ok) ok = rec_clear(w, static_cast<int>(off) + (type == 4 ? 119 : 213), type == 4 ? 9 : 43);
        } else {
            ok = decode_ni(w, static_cast<int>(off), n);
            if (ok) {
                if (type == 3) ok = decode_type3(w, static_cast<int>(off), n);
                else ok = decode_children(w, static_cast<int>(off) + OFF_CHILD, n, type == 1 ? 2 : 6);
                if (ok) {
                    int rsv = (type == 3) ? (249) : (255);
                    int rsv_w = (type == 3) ? 7 : 1;
                    ok = rec_clear(w, static_cast<int>(off) + rsv, rsv_w);
                }
            }
        }
        if (!ok) return false;
"""
new_visit_tail = """        bool ok = true;
        if (type == 4 || type == 5) {
            ok = decode_inline(w, static_cast<int>(off), n);
        } else {
            ok = decode_ni(w, static_cast<int>(off), n);
            if (ok) {
                if (type == 3) {
                    ok = decode_children(w, static_cast<int>(off) + OFF_DIRECT3, n, 3) &&
                         decode_type3(w, static_cast<int>(off), n);
                } else {
                    ok = decode_children(w, static_cast<int>(off) + OFF_CHILD, n, type == 1 ? 2 : 6);
                }
            }
        }
        // Reserved bits of every record layout must be zero.
        if (ok) {
            int rsv_off = 0, rsv_w = 0;
            switch (type) {
                case 1: rsv_off = 127; rsv_w = 1; break;
                case 2: rsv_off = 255; rsv_w = 1; break;
                case 3: rsv_off = 249; rsv_w = 7; break;
                case 4: rsv_off = 119; rsv_w = 9; break;
                default: rsv_off = 213; rsv_w = 43; break;
            }
            ok = rec_clear(w, static_cast<int>(off) + rsv_off, rsv_w);
        }
        if (!ok) return false;
"""
assert old_visit_tail in s
s=s.replace(old_visit_tail,new_visit_tail)

old_rec = """        // Children, strictly lower stages, six bits deeper.
        if (!n.edges.empty() && depth + 6 > omax) return false;
        uint32_t prev_key = 0;
        bool first_edge = true;
        uint32_t total = n.own.size();
        for (size_t i = 0; i < n.edges.size(); ++i) {
            const VEdge& e = n.edges[i];
            if (!first_edge && e.key <= prev_key) return false;
            first_edge = false;
            prev_key = e.key;
            if (e.stage >= stage) return false;  // strictly lower than the parent
            uint64_t chi = rhi, clo = rlo;
            fib_set_bits(chi, clo, depth, 6, e.key);
            uint32_t cidx;
            if (!visit(e.stage, e.cell, stage, e.bulk_child, origin, depth + 6, chi, clo, cidx)) return false;
            total += nodes_[cidx].size;
        }
        n.size = total;"""
new_rec = """        // Children, strictly lower stages, six bits deeper.  Copies are taken
        // because the recursion below grows nodes_ and would invalidate 'n'.
        if (!nodes_[idx].edges.empty() && depth + 6 > omax) return false;
        std::vector<VEdge> edges = nodes_[idx].edges;
        uint32_t prev_key = 0;
        bool first_edge = true;
        uint32_t total = static_cast<uint32_t>(nodes_[idx].own.size());
        for (size_t i = 0; i < edges.size(); ++i) {
            const VEdge& e = edges[i];
            if (!first_edge && e.key <= prev_key) return false;
            first_edge = false;
            prev_key = e.key;
            if (e.stage >= stage) return false;  // strictly lower than the parent
            uint64_t chi = rhi, clo = rlo;
            fib_set_bits(chi, clo, depth, 6, e.key);
            uint32_t cidx;
            if (!visit(e.stage, e.cell, stage, e.bulk_child, origin, depth + 6, chi, clo, cidx)) return false;
            total += nodes_[cidx].size;
        }
        nodes_[idx].size = total;"""
assert old_rec in s
s=s.replace(old_rec,new_rec)

s=s.replace("""        if (type == 4 && total != 1) return false;
        if (type == 5 && total != 2) return false;
        if (type != 4 && type != 5 && total < 3) return false;""",
"""        if (type == 4 && total != 1) return false;
        if (type == 5 && total != 2) return false;
        if (type != 4 && type != 5 && total < 3) return false;
        if (type == 3 && (edges.size() < 7 || edges.size() > 64)) return false;""")

# decode_type3: parse nothing about direct children; it uses n.edges already filled
s=s.replace("""        std::vector<VEdge> direct = n.edges;  // already sorted by key""",
"""        std::vector<VEdge> direct = n.edges;  // the at most three direct slots""")
open(p,'w').write(s)
print("patched")
PY
